import { createAudioPlayer, type AudioPlayer } from 'expo-audio';

import { useSettingsStore } from '@/store/settings-store';

export type SoundCue = 'ready' | 'stop' | 'warning' | 'record';

// Short tones generated by scripts/generate-sounds.mjs and bundled with the app.
const SOURCES: Record<SoundCue, number> = {
  ready: require('../../assets/sounds/ready.wav'),
  stop: require('../../assets/sounds/stop.wav'),
  warning: require('../../assets/sounds/warning.wav'),
  record: require('../../assets/sounds/record.wav'),
};

const players = new Map<SoundCue, AudioPlayer>();

/** One player per sound, created on first use and reused, so playing is instant. */
function player(cue: SoundCue): AudioPlayer {
  let p = players.get(cue);
  if (!p) {
    p = createAudioPlayer(SOURCES[cue]);
    players.set(cue, p);
  }
  return p;
}

/**
 * Fire-and-forget sound feedback, respecting the user's setting. Like haptics, it is
 * only ever called after the timestamp it relates to has been recorded.
 */
export function playSound(cue: SoundCue): void {
  if (!useSettingsStore.getState().timer.soundEnabled) return;
  try {
    const p = player(cue);
    p.seekTo(0).catch(() => {});
    p.play();
  } catch {
    // A device without audio output (or a failed load) just stays silent.
  }
}
